AP@K is computed using the following Python code:
from collections import Counter
from itertools import chain

def apk(predictions, K=5):
    """Compute average precision at K for a list of predictions."""
    if not predictions:
        return 0.0
    prediction_ids = list(chain.from_iterable(map(int, predictions)))
    # Sort the prediction_ids and find the indices of the predictions.
    sorted_indicies = sorted(
        chain.from_iterable(
            map(
                lambda x: [index for index, val in enumerate(predictions) if val == prediction_ids[x]],
                zip(*[(i, 1) for i in range(len(predictions))], list(range(len(predictions)))),
            )
        )
    ),
    key=lambda x: x[0],
    reverse=True,
    )
    # Compute the average precision.
    ap = sum(
        [
            Counter(
                [
                    [index, 1]
                    for index in prediction_ids
                    if prediction_ids[index] in sorted_indicies
                ]
                ).get(index, 0) / len(sorted_indicies)
                for _ in range(K)
            )
        ]
    ) / K
    return ap

